-- Resolve columns to flattened row slots, and validate before any execution.
import Json (..)
import Model (..)
import Data.List (..)
import Data.Foldable (all, any, length)

fn compatible(ts : List(String)) : Bool =
  let concrete = filter(\(t) -> t /= "null", ts)
  length(concrete) == 0 || all(\(t) -> t == at(concrete, 0), concrete)

fn common_kind(ts : List(String)) : String =
  let concrete = filter(\(t) -> t /= "null", ts)
  if length(concrete) == 0 then "null" else at(concrete, 0)

fn check(e : Expr, columns : List(Column), allow : Bool, inside : Bool) : Expr =
  if e.op == "col" then
    let matches = filter(
        \(c) -> c.name == e.name && (e.qualifier == "" || e.qualifier == c.qualifier),
        columns,
      )
    demand(length(matches) > 0, "UNKNOWN_COLUMN")
    demand(length(matches) == 1, "AMBIGUOUS_COLUMN")
    let c = at(matches, 0)
    Expr { ..e, index = c.index, source = c.source, kind = c.kind }
  elif e.op == "lit" then
    e
  else
    let isagg = agg(e.op)
    demand(not(isagg) || allow && not(inside), "INVALID_AGGREGATION")
    let args = map(\(a) -> check(a, columns, allow, inside || isagg), e.args)
    let ts = map(\(a) -> a.kind, args)
    let kind =
      if e.op == "COUNT" then
        "int"
      elif elem(e.op, ["SUM", "+", "-", "*"]) then
        demand(all(\(t) -> elem(t, ["int", "null"]), ts), "TYPE_ERROR")
        "int"
      elif elem(e.op, ["MIN", "MAX"]) then
        demand(elem(at(ts, 0), ["int", "text"]), "TYPE_ERROR")
        at(ts, 0)
      elif elem(e.op, ["NOT", "AND", "OR"]) then
        demand(all(\(t) -> elem(t, ["bool", "null"]), ts), "TYPE_ERROR")
        "bool"
      elif elem(e.op, ["ISNULL", "ISNOTNULL"]) then
        "bool"
      elif e.op == "COALESCE" then
        demand(compatible(ts), "TYPE_ERROR")
        common_kind(ts)
      else
        demand(
            compatible(ts)
              && (common_kind(ts) /= "bool" || elem(e.op, ["=", "<>"])),
            "TYPE_ERROR",
          )
        "bool"
    Expr { ..e, args = args, kind = kind }

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(elem(b.kind, ["bool", "null"]), "TYPE_ERROR")
  b

pub fn tree_any(p : (Expr) -> Bool, e : Expr) : Bool =
  p(e) || any(\(a) -> tree_any(p, a), e.args)

fn grouped(e : Expr, keys : List(Int)) : Unit =
  if not(agg(e.op)) then
    demand(e.op /= "col" || elem(e.index, keys), "INVALID_AGGREGATION")
    for a in sof(e.args) do
      grouped(a, keys)

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

pub fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let cs = map(
        \(k) -> Column {
          ..at(t.columns, k),
          index = offset + k,
          source = i,
          qualifier = qualifier,
          nullable = at(t.columns, k).nullable || i > 0 && at(q.left_joins, i - 1)
        },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\((name, desc, nulls)) -> (alias_index(aliases, name, 0), desc, nulls), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

fn alias_index(names : List(String), n : String, i : Int) : Int =
  match names of
    Nil =>
      reject("UNKNOWN_COLUMN")
      -1
    Cons(a, rest) =>
      if a == n then
        i
      else
        alias_index(rest, n, i + 1)

-- Checkpoint-two command protocol and materialized-view ownership.
-- Base rows retain private identifiers while SQL continues to see ordinary Tables.
import Json (..)
import Model (..)
import Parser (parse_sql)
import Binder (bind)
import Engine (execute, optimize)
import Data.List (..)
import Data.Foldable (all, any, length)

pub type StoredRow = StoredRow { id: Int, values: List(Json) }

pub type LiveTable = LiveTable {
  name: String,
  columns: List(Column),
  rows: List(StoredRow),
  used: List(Int)
}

pub type View = View {
  name: String,
  plan: Plan,
  dependencies: List(String),
  result: Json
}

pub type Store = Store {
  tables: List(LiveTable),
  views: List(View),
  revision: Int
}

type CommandResult = CommandResult { store: Store, reply: Json }

fn good(value : Json) : Json =
  JObj([("ok", JBool(true)), ("result", value)])

fn bad(code : String) : Json =
  JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

fn command_fields(j : Json, names : List(String)) : Unit =
  match j of
    JObj(xs) =>
      demand(length(xs) == length(names), "INVALID_COMMAND")
      demand(all(\(n) -> length(filter(\(kv) -> fst(kv) == n, xs)) == 1, names), "INVALID_COMMAND")
    _ => reject("INVALID_COMMAND")

fn command_field(j : Json, name : String) : Json =
  match j of
    JObj(xs) => command_lookup(xs, name)
    _ =>
      reject("INVALID_COMMAND")
      JNull

fn command_lookup(xs : List((String, Json)), name : String) : Json =
  match xs of
    Nil =>
      reject("INVALID_COMMAND")
      JNull
    Cons((k, v), rest) => if k == name then v else command_lookup(rest, name)

fn command_text(j : Json, name : String) : String =
  match command_field(j, name) of
    JStr(s) => s
    _ =>
      reject("INVALID_COMMAND")
      ""

fn command_int(j : Json, name : String) : Int =
  match command_field(j, name) of
    JInt(n) =>
      demand(n >= 1 && n <= 2147483647, "INVALID_COMMAND")
      n
    _ =>
      reject("INVALID_COMMAND")
      0

fn view_name_ok(s : String) : Bool =
  byte_len(s) >= 1 && byte_len(s) <= 40
    && byte_at(s, 0) >= 97 && byte_at(s, 0) <= 122
    && all(
        \(i) ->
          let c = byte_at(s, i) in
          c >= 97 && c <= 122 || digit(c) || c == 45,
        range(0, byte_len(s)),
      )

fn table_name_shape(s : String) : Bool =
  byte_len(s) > 0 && letter(byte_at(s, 0))
    && all(\(i) -> letter(byte_at(s, i)) || digit(byte_at(s, i)), range(0, byte_len(s)))

pub fn initial_store(database : List(Table)) : Store =
  Store {
    tables = map(
        \(t) -> LiveTable {
          name = t.name,
          columns = t.columns,
          rows = map(\(i) -> StoredRow { id = i + 1, values = at(t.rows, i) }, range(0, length(t.rows))),
          used = range(1, length(t.rows) + 1)
        },
        database,
      ),
    views = [],
    revision = 0
  }

fn database_of(tables : List(LiveTable)) : List(Table) =
  map(
      \(t) -> Table { name = t.name, columns = t.columns, rows = map(\(r) -> r.values, t.rows) },
      tables,
    )

fn find_live(tables : List(LiveTable), name : String) : LiveTable =
  match tables of
    Nil =>
      reject("UNKNOWN_TABLE")
      at(tables, 0)
    Cons(t, rest) => if t.name == name then t else find_live(rest, name)

fn replace_live(tables : List(LiveTable), table : LiveTable) : List(LiveTable) =
  match tables of
    Nil => []
    Cons(t, rest) =>
      if t.name == table.name then Cons(table, rest) else Cons(t, replace_live(rest, table))

fn find_view(views : List(View), name : String) : View =
  match views of
    Nil =>
      reject("UNKNOWN_VIEW")
      at(views, 0)
    Cons(v, rest) => if v.name == name then v else find_view(rest, name)

fn has_view(views : List(View), name : String) : Bool =
  any(\(v) -> v.name == name, views)

fn remove_view(views : List(View), name : String) : List(View) =
  filter(\(v) -> v.name /= name, views)

fn bounded_value(value : Json) : Bool =
  match value of
    JInt(n) => n >= -1000000000 && n <= 1000000000
    _ => true

fn valid_row(row : List(Json), columns : List(Column)) : Bool =
  length(row) == length(columns)
    && all(
        \(i) ->
          let value = at(row, i) in
          let column = at(columns, i) in
          bounded_value(value)
            && (value_type(value) == column.kind || is_null(value) && column.nullable),
        range(0, length(columns)),
      )

fn row_at(rows : List(StoredRow), id : Int) : StoredRow =
  match rows of
    Nil =>
      reject("UNKNOWN_ROW")
      at(rows, 0)
    Cons(r, rest) => if r.id == id then r else row_at(rest, id)

fn update_row(rows : List(StoredRow), id : Int, values : List(Json)) : List(StoredRow) =
  match rows of
    Nil => []
    Cons(r, rest) =>
      if r.id == id then Cons(StoredRow { id = id, values = values }, rest)
      else Cons(r, update_row(rest, id, values))

fn check_change_shape(change : Json) : Unit =
  let op = command_text(change, "op")
  if op == "insert" || op == "update" then
    command_fields(change, ["op", "table", "id", "row"])
    let table = command_text(change, "table")
    demand(table_name_shape(table), "INVALID_COMMAND")
    let ignored_id = command_int(change, "id")
    match command_field(change, "row") of
      JArr(_) => ()
      _ => reject("INVALID_COMMAND")
  elif op == "delete" then
    command_fields(change, ["op", "table", "id"])
    let table = command_text(change, "table")
    demand(table_name_shape(table), "INVALID_COMMAND")
    let ignored_id = command_int(change, "id")
    ()
  else
    reject("INVALID_COMMAND")

fn change_row(change : Json) : List(Json) =
  match command_field(change, "row") of
    JArr(xs) => xs
    _ => []

fn apply_change(tables : List(LiveTable), change : Json) : List(LiveTable) =
  let op = command_text(change, "op")
  let name = command_text(change, "table")
  let id = command_int(change, "id")
  let table = find_live(tables, name)
  let changed =
    if op == "insert" then
      let values = change_row(change) in
      demand(valid_row(values, table.columns), "INVALID_ROW")
      demand(not(elem(id, table.used)), "ROW_ID_USED")
      LiveTable { ..table, rows = append(table.rows, [StoredRow { id = id, values = values }]), used = Cons(id, table.used) }
    elif op == "update" then
      let values = change_row(change) in
      demand(valid_row(values, table.columns), "INVALID_ROW")
      let ignored = row_at(table.rows, id)
      LiveTable { ..table, rows = update_row(table.rows, id, values) }
    else
      let ignored = row_at(table.rows, id)
      LiveTable { ..table, rows = filter(\(r) -> r.id /= id, table.rows) }
  replace_live(tables, changed)

fn changed_names(changes : List(Json)) : List(String) =
  unique_names(map(\(c) -> command_text(c, "table"), changes))

fn unique_names(xs : List(String)) : List(String) =
  match xs of
    Nil => []
    Cons(x, rest) => Cons(x, unique_names(filter(\(y) -> y /= x, rest)))

-- Bound expressions and optimizer decisions are retained.  Only a plan's table
-- snapshots are replaced, and only for views depending on a changed table.
fn refresh_plan(plan : Plan, database : List(Table)) : Plan =
  let tables = map(
      \(source) ->
        let matches = filter(\(t) -> t.name == fst(source), database) in at(matches, 0),
      plan.query.sources,
    )
  Plan { ..plan, tables = tables }

fn maintain(views : List(View), tables : List(LiveTable), changed : List(String)) : List(View) =
  let database = database_of(tables)
  map(
      \(view) ->
        if any(\(name) -> elem(name, changed), view.dependencies) then
          let plan = refresh_plan(view.plan, database) in
          View { ..view, plan = plan, result = execute(plan) }
        else
          view,
      views,
    )

fn result_with_revision(result : Json, revision : Int) : Json =
  match result of
    JObj(xs) => JObj(Cons(("revision", JInt(revision)), xs))
    _ => result

fn run_command(command : Json, store : Store) : CommandResult =
  let op = command_text(command, "op")
  if op == "create" then
    command_fields(command, ["op", "view", "sql", "optimize"])
    let name = command_text(command, "view")
    demand(view_name_ok(name), "INVALID_COMMAND")
    let sql = command_text(command, "sql")
    let optimized =
      match command_field(command, "optimize") of
        JBool(b) => b
        _ =>
          reject("INVALID_COMMAND")
          false
    demand(not(has_view(store.views, name)), "VIEW_EXISTS")
    let raw = bind(parse_sql(sql), database_of(store.tables))
    let plan = if optimized then optimize(raw) else raw
    let view = View { name = name, plan = plan, dependencies = unique_names(map(fst, plan.query.sources)), result = execute(plan) }
    CommandResult {
      store = Store { ..store, views = append(store.views, [view]) },
      reply = good(JObj([("view", JStr(name)), ("revision", JInt(store.revision))]))
    }
  elif op == "read" then
    command_fields(command, ["op", "view"])
    let name = command_text(command, "view")
    demand(view_name_ok(name), "INVALID_COMMAND")
    let view = find_view(store.views, name)
    CommandResult { store = store, reply = good(result_with_revision(view.result, store.revision)) }
  elif op == "drop" then
    command_fields(command, ["op", "view"])
    let name = command_text(command, "view")
    demand(view_name_ok(name), "INVALID_COMMAND")
    let ignored = find_view(store.views, name)
    CommandResult {
      store = Store { ..store, views = remove_view(store.views, name) },
      reply = good(JObj([("dropped", JStr(name))]))
    }
  elif op == "apply" then
    command_fields(command, ["op", "changes"])
    let changes =
      match command_field(command, "changes") of
        JArr(xs) => xs
        _ =>
          reject("INVALID_COMMAND")
          []
    demand(length(changes) >= 1 && length(changes) <= 200, "INVALID_COMMAND")
    for change in sof(changes) do check_change_shape(change)
    var tables := store.tables
    for change in sof(changes) do tables := apply_change(tables, change)
    let views = maintain(store.views, tables, changed_names(changes))
    let next = Store { tables = tables, views = views, revision = store.revision + 1 }
    CommandResult { store = next, reply = good(JObj([("revision", JInt(next.revision))])) }
  else
    reject("INVALID_COMMAND")
    CommandResult { store = store, reply = JNull }

fn process(commands : List(Json), store : Store) : List(Json) =
  match commands of
    Nil => []
    Cons(command, rest) =>
      let outcome =
        handle run_command(command, store) with
          never reject(code) => CommandResult { store = store, reply = bad(code) }
          return result => result
      Cons(outcome.reply, process(rest, outcome.store))

pub fn run_commands(database : List(Table), commands : List(Json)) : Json =
  JObj([
      ("ok", JBool(true)),
      ("result", JObj([("results", JArr(process(commands, initial_store(database))))])),
    ])

-- The parser owns a scoped token-state effect; all ASTs are immutable values.
import Json (..)
import Data.String (..)
import Data.List (..)
import Data.Foldable (all, length)
import Model (..)
import Control.State (..)

pub type Token = Token { word: String, value: Json }

fn tok(s : String) : Token = Token { word = s, value = JNull }

fn scan_string(s : String, i : Int, acc : String) : (String, Int) =
  demand(i < byte_len(s), "PARSE_ERROR")
  if byte_at(s, i) == 39 then
    if i + 1 < byte_len(s) && byte_at(s, i + 1) == 39 then
      scan_string(s, i + 2, concat(acc, "'"))
    else
      (acc, i + 1)
  else
    scan_string(s, i + 1, concat(acc, str_of_char(chr(byte_at(s, i)))))

fn scan_word(s : String, i : Int, numbers : Bool) : Int =
  if i >= byte_len(s) then
    i
  else
    let c = byte_at(s, i)
    if (digit(c) || not(numbers) && (letter(c) || c >= 65 && c <= 90)) then
      scan_word(s, i + 1, numbers)
    else
      i

fn slice(s : String, i : Int, j : Int) : String =
  string_of_buf(slice_bytes(s, i, j, buf_empty()))

fn lex(s : String, i : Int) : List(Token) =
  if i >= byte_len(s) then
    [tok("$END")]
  else
    let c = byte_at(s, i)
    if elem(c, [32, 9, 10, 13]) then
      lex(s, i + 1)
    elif c == 39 then
      let (v, j) = scan_string(s, i + 1, "")
      Cons(Token { word = "LITERAL", value = JStr(v) }, lex(s, j))
    elif digit(c) then
      let j = scan_word(s, i, true)
      let n =
        match parse_int(slice(s, i, j)) of
          Some(v) => v
          None => 0
      Cons(Token { word = "NUMBER", value = JInt(n) }, lex(s, j))
    elif letter(c) || c >= 65 && c <= 90 then
      let j = scan_word(s, i, false)
      let w = slice(s, i, j)
      Cons(tok(if reserved(w) then to_upper(w) else w), lex(s, j))
    else
      let two = slice(s, i, min(i + 2, byte_len(s)))
      if elem(two, ["<>", "<=", ">="]) then
        Cons(tok(two), lex(s, i + 2))
      else
        demand(
            elem(c, [40, 41, 44, 46, 59, 43, 45, 42, 61, 60, 62]),
            "PARSE_ERROR",
          )
        Cons(tok(str_of_char(chr(c))), lex(s, i + 1))

fn peek() : String ! {State(List(Token))} = at(get(), 0).word

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn accept(w : String) : Bool ! {State(List(Token))} =
  if peek() == w then
    let ts = get()
    put(tail(ts))
    true
  else
    false

fn expect(w : String) : Unit = demand(accept(w), "PARSE_ERROR")

fn name() : String =
  let w = pop().word
  demand(name_ok(w), "PARSE_ERROR")
  w

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn precedence(op : String) : Int =
  if op == "OR" then
    1
  elif op == "AND" then
    2
  elif elem(op, ["=", "<>", "<", ">", "<=", ">="]) then
    4
  elif elem(op, ["+", "-"]) then
    5
  elif op == "*" then
    6
  else
    0

fn expression(minimum : Int) : Expr =
  let t = pop()
  let w = t.word
  let e =
    if w == "NOT" then
      node(w, [expression(3)])
    elif w == "(" then
      let x = expression(1)
      expect(")")
      x
    elif w == "-" then
      literal(JInt(-natural()))
    elif elem(w, ["NUMBER", "LITERAL"]) then
      literal(t.value)
    elif elem(w, ["TRUE", "FALSE"]) then
      literal(JBool(w == "TRUE"))
    elif w == "NULL" then
      literal(JNull)
    elif w == "COALESCE" then
      expect("(")
      let first = expression(1)
      expect(",")
      let args = coalesce_args([first])
      expect(")")
      node("COALESCE", args)
    elif agg(w) then
      expect("(")
      let args =
        if w == "COUNT" && accept("*") then
          []
        else
          [expression(1)]
      expect(")")
      node(w, args)
    else
      demand(name_ok(w), "PARSE_ERROR")
      if accept(".") then
        column_ref(w, name())
      else
        column_ref("", w)
  binary(e, minimum, false)

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  let p = if op == "IS" then 4 else precedence(op)
  if p < minimum then
    left
  else
    demand(not(p == 4 && compared), "PARSE_ERROR")
    let ignored = pop()
    if op == "IS" then
      let negated = accept("NOT")
      expect("NULL")
      binary(node(if negated then "ISNOTNULL" else "ISNULL", [left]), minimum, true)
    else
      let right = expression(p + 1)
      binary(node(op, [left, right]), minimum, compared || p == 4)

fn coalesce_args(acc : List(Expr)) : List(Expr) =
  let e = expression(1)
  let next = append(acc, [e])
  if accept(",") then coalesce_args(next) else next

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Bool, Int)) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let nulls =
    if accept("NULLS") then
      if accept("FIRST") then 1 elif accept("LAST") then 2 else
        reject("PARSE_ERROR")
        0
    else
      0
  Cons((n, desc, nulls), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr),
  ls : List(Bool)
) : (List((String, String)), List(Expr), List(Bool)) =
  if elem(peek(), ["INNER", "JOIN", "LEFT"]) then
    let left = accept("LEFT")
    if left then let ignored = accept("OUTER") in () else let ignored = accept("INNER") in ()
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [left]))
  else
    (ss, js, ls)

fn query() : Query =
  expect("SELECT")
  let distinct = accept("DISTINCT")
  let sels = selections()
  expect("FROM")
  let (ss, js, ls) = join_sources([source()], [], [])
  let pred =
    if accept("WHERE") then
      expression(1)
    else
      literal(JBool(true))
  let groups =
    if accept("GROUP") then
      expect("BY")
      group_keys()
    else
      []
  let hh = accept("HAVING")
  let hav =
    if hh then
      expression(1)
    else
      literal(JBool(true))
  let order =
    if accept("ORDER") then
      expect("BY")
      order_keys()
    else
      []
  let lim =
    if accept("LIMIT") then
      natural()
    else
      -1
  let off =
    if lim >= 0 && accept("OFFSET") then
      natural()
    else
      0
  let ignored = accept(";")
  demand(peek() == "$END", "PARSE_ERROR")
  Query {
    select = sels,
    sources = ss,
    joins = js,
    left_joins = ls,
    predicate = pred,
    groups = groups,
    having = hav,
    has_having = hh,
    order = order,
    distinct = distinct,
    limit = lim,
    offset = off
  }

pub fn parse_sql(s : String) : Query = eval_state(lex(s, 0), query)

-- One request, one response. Domain effects abort the complete query batch.
import Json (..)
import Model (..)
import Parser (..)
import Binder (..)
import Engine (..)
import Commands (run_commands)
import Data.List (..)
import Data.Foldable (length)

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

fn has_field(j : Json, name : String) : Bool =
  match j of
    JObj(xs) => length(filter(\(kv) -> fst(kv) == name, xs)) > 0
    _ => false

fn work(request : Json) : Json =
  fields(request, ["protocol_version", "task", "input"])
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  let query_mode = has_field(input, "queries") && not(has_field(input, "commands"))
  let command_mode = has_field(input, "commands") && not(has_field(input, "queries"))
  demand(query_mode || command_mode, "INVALID_INPUT")
  fields(input, if query_mode then ["database", "queries"] else ["database", "commands"])
  let database = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, database)), "INVALID_INPUT")
  if command_mode then
    let commands = arr(getfield(input, "commands"))
    demand(length(commands) <= 2000, "INVALID_INPUT")
    run_commands(database, commands)
  else
    let queries = arr(getfield(input, "queries"))
    for q in sof(queries) do
      validate_query(q)
    let results = map(
        \(q) -> let plan = bind(parse_sql(text(getfield(q, "sql"))), database) in execute(if truth(getfield(q, "optimize")) then optimize(plan) else plan),
        queries,
      )
    JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(results))]))])

fn error_response(code : String) : Json =
  JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

fn decode_work(line : String) : Json =
  match decode_lossy(line) of
    Ok(request) => work(request)
    Err(_) => error_response("INVALID_INPUT")

fn main() =
  let line = read_line()
  let response =
    handle decode_work(line) with
      never reject(code) => error_response(code)
      return result => result
  println(encode(response))

