fn compatible(ts : List(String)) : Bool =
  let concrete = filter(\(t) -> t /= "null", ts)
  length(concrete) == 0 || all(\(t) -> t == at(concrete, 0), concrete)

fn common_kind(ts : List(String)) : String =
  let concrete = filter(\(t) -> t /= "null", ts)
  if length(concrete) == 0 then "null" else at(concrete, 0)

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(elem(b.kind, ["bool", "null"]), "TYPE_ERROR")
  b

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let cs = map(
        \(k) -> Column {
          ..at(t.columns, k),
          index = offset + k,
          source = i,
          qualifier = qualifier,
          nullable = at(t.columns, k).nullable || i > 0 && at(q.left_joins, i - 1)
        },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\((name, desc, nulls)) -> (alias_index(aliases, name, 0), desc, nulls), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

type LiveTable = LiveTable {
  name: String,
  columns: List(Column),
  rows: List(StoredRow),
  used: List(Int)
}

type View = View {
  name: String,
  plan: Plan,
  dependencies: List(String),
  result: Json
}

type Store = Store {
  tables: List(LiveTable),
  views: List(View),
  revision: Int
}

fn table_name_shape(s : String) : Bool =
  byte_len(s) > 0 && letter(byte_at(s, 0))
    && all(\(i) -> letter(byte_at(s, i)) || digit(byte_at(s, i)), range(0, byte_len(s)))

fn initial_store(database : List(Table)) : Store =
  Store {
    tables = map(
        \(t) -> LiveTable {
          name = t.name,
          columns = t.columns,
          rows = map(\(i) -> StoredRow { id = i + 1, values = at(t.rows, i) }, range(0, length(t.rows))),
          used = range(1, length(t.rows) + 1)
        },
        database,
      ),
    views = [],
    revision = 0
  }

fn database_of(tables : List(LiveTable)) : List(Table) =
  map(
      \(t) -> Table { name = t.name, columns = t.columns, rows = map(\(r) -> r.values, t.rows) },
      tables,
    )

fn replace_live(tables : List(LiveTable), table : LiveTable) : List(LiveTable) =
  match tables of
    Nil => []
    Cons(t, rest) =>
      if t.name == table.name then Cons(table, rest) else Cons(t, replace_live(rest, table))

fn update_row(rows : List(StoredRow), id : Int, values : List(Json)) : List(StoredRow) =
  match rows of
    Nil => []
    Cons(r, rest) =>
      if r.id == id then Cons(StoredRow { id = id, values = values }, rest)
      else Cons(r, update_row(rest, id, values))

fn check_change_shape(change : Json) : Unit =
  let op = command_text(change, "op")
  if op == "insert" || op == "update" then
    command_fields(change, ["op", "table", "id", "row"])
    let table = command_text(change, "table")
    demand(table_name_shape(table), "INVALID_COMMAND")
    let ignored_id = command_int(change, "id")
    match command_field(change, "row") of
      JArr(_) => ()
      _ => reject("INVALID_COMMAND")
  elif op == "delete" then
    command_fields(change, ["op", "table", "id"])
    let table = command_text(change, "table")
    demand(table_name_shape(table), "INVALID_COMMAND")
    let ignored_id = command_int(change, "id")
    ()
  else
    reject("INVALID_COMMAND")

fn apply_change(tables : List(LiveTable), change : Json) : List(LiveTable) =
  let op = command_text(change, "op")
  let name = command_text(change, "table")
  let id = command_int(change, "id")
  let table = find_live(tables, name)
  let changed =
    if op == "insert" then
      let values = change_row(change) in
      demand(valid_row(values, table.columns), "INVALID_ROW")
      demand(not(elem(id, table.used)), "ROW_ID_USED")
      LiveTable { ..table, rows = append(table.rows, [StoredRow { id = id, values = values }]), used = Cons(id, table.used) }
    elif op == "update" then
      let values = change_row(change) in
      demand(valid_row(values, table.columns), "INVALID_ROW")
      let ignored = row_at(table.rows, id)
      LiveTable { ..table, rows = update_row(table.rows, id, values) }
    else
      let ignored = row_at(table.rows, id)
      LiveTable { ..table, rows = filter(\(r) -> r.id /= id, table.rows) }
  replace_live(tables, changed)

fn refresh_plan(plan : Plan, database : List(Table)) : Plan =
  let tables = map(
      \(source) ->
        let matches = filter(\(t) -> t.name == fst(source), database) in at(matches, 0),
      plan.query.sources,
    )
  Plan { ..plan, tables = tables }

fn maintain(views : List(View), tables : List(LiveTable), changed : List(String)) : List(View) =
  let database = database_of(tables)
  map(
      \(view) ->
        if any(\(name) -> elem(name, changed), view.dependencies) then
          let plan = refresh_plan(view.plan, database) in
          View { ..view, plan = plan, result = execute(plan) }
        else
          view,
      views,
    )

fn run_command(command : Json, store : Store) : CommandResult =
  let op = command_text(command, "op")
  if op == "create" then
    command_fields(command, ["op", "view", "sql", "optimize"])
    let name = command_text(command, "view")
    demand(view_name_ok(name), "INVALID_COMMAND")
    let sql = command_text(command, "sql")
    let optimized =
      match command_field(command, "optimize") of
        JBool(b) => b
        _ =>
          reject("INVALID_COMMAND")
          false
    demand(not(has_view(store.views, name)), "VIEW_EXISTS")
    let raw = bind(parse_sql(sql), database_of(store.tables))
    let plan = if optimized then optimize(raw) else raw
    let view = View { name = name, plan = plan, dependencies = unique_names(map(fst, plan.query.sources)), result = execute(plan) }
    CommandResult {
      store = Store { ..store, views = append(store.views, [view]) },
      reply = good(JObj([("view", JStr(name)), ("revision", JInt(store.revision))]))
    }
  elif op == "read" then
    command_fields(command, ["op", "view"])
    let name = command_text(command, "view")
    demand(view_name_ok(name), "INVALID_COMMAND")
    let view = find_view(store.views, name)
    CommandResult { store = store, reply = good(result_with_revision(view.result, store.revision)) }
  elif op == "drop" then
    command_fields(command, ["op", "view"])
    let name = command_text(command, "view")
    demand(view_name_ok(name), "INVALID_COMMAND")
    let ignored = find_view(store.views, name)
    CommandResult {
      store = Store { ..store, views = remove_view(store.views, name) },
      reply = good(JObj([("dropped", JStr(name))]))
    }
  elif op == "apply" then
    command_fields(command, ["op", "changes"])
    let changes =
      match command_field(command, "changes") of
        JArr(xs) => xs
        _ =>
          reject("INVALID_COMMAND")
          []
    demand(length(changes) >= 1 && length(changes) <= 200, "INVALID_COMMAND")
    for change in sof(changes) do check_change_shape(change)
    var tables := store.tables
    for change in sof(changes) do tables := apply_change(tables, change)
    let views = maintain(store.views, tables, changed_names(changes))
    let next = Store { tables = tables, views = views, revision = store.revision + 1 }
    CommandResult { store = next, reply = good(JObj([("revision", JInt(next.revision))])) }
  else
    reject("INVALID_COMMAND")
    CommandResult { store = store, reply = JNull }

fn process(commands : List(Json), store : Store) : List(Json) =
  match commands of
    Nil => []
    Cons(command, rest) =>
      let outcome =
        handle run_command(command, store) with
          never reject(code) => CommandResult { store = store, reply = bad(code) }
          return result => result
      Cons(outcome.reply, process(rest, outcome.store))

fn run_commands(database : List(Table), commands : List(Json)) : Json =
  JObj([
      ("ok", JBool(true)),
      ("result", JObj([("results", JArr(process(commands, initial_store(database))))])),
    ])

fn coalesce(args : List(Expr), row : List(Json), group : List(List(Json))) : Json =
  match args of
    Nil => JNull
    Cons(e, rest) =>
      let v = evaluate(e, row, group)
      if is_null(v) then coalesce(rest, row, group) else v

fn fold_constants(e : Expr) : Expr =
  let n = Expr { ..e, args = map(fold_constants, e.args) }
  if (not(agg(n.op))
      && not(elem(n.op, ["lit", "col"]))
      && all(\(a) -> a.op == "lit", n.args)) then
    literal(evaluate(n, [], []))
  else
    n

fn combine(es : List(Expr)) : Expr =
  match es of
    Nil => literal(JBool(true))
    Cons(e, Nil) => e
    Cons(e, rest) => Expr { ..node("AND", [e, combine(rest)]), kind = "bool" }

fn optimize(plan : Plan) : Plan =
  let q = plan.query
  let terms = conjuncts(fold_constants(q.predicate))
  let pushable = \(e) -> can_push(e, length(plan.tables), q.left_joins)
  let fs = map(
      \(i) -> filter(\(e) -> pushable(e) && at(sources(e), 0) == i, terms),
      range(0, length(plan.tables)),
    )
  let rem = filter(\(e) -> not(pushable(e)), terms)
  let bq = Query {
    ..q,
    predicate = combine(rem),
    select = map(\(s) -> (fold_constants(fst(s)), snd(s)), q.select),
    joins = map(fold_constants, q.joins),
    having = fold_constants(q.having)
  }
  Plan { ..plan, query = bq, filters = fs }

fn execute(plan : Plan) : Json =
  let q = plan.query
  var scans := []
  var offset := 0
  for i in srange(0, length(plan.tables)) do
    let t = at(plan.tables, i)
    let padding = replicate(offset, JNull)
    let predicates = at(plan.filters, i)
    let rs = filter(
        \(r) -> all(\(p) -> truth(evaluate(p, append(padding, r), [])), predicates),
        t.rows,
      )
    scans := append(scans, [rs])
    offset += length(t.columns)
  var rows := at(scans, 0)
  for i in srange(0, length(q.joins)) do
    rows := join_rows(
        rows,
        at(scans, i + 1),
        at(q.joins, i),
        at(q.left_joins, i),
        length(at(plan.tables, i + 1).columns),
      )
  let filtered = filter(\(r) -> truth(evaluate(q.predicate, r, [])), rows)
  let projected =
    if plan.aggregate then
      flatten(
          map(
              \(g) -> project(q, if length(g.rows) > 0 then at(g.rows, 0) else [], g.rows),
              groups_for(filtered, q.groups),
            ),
        )
    else
      flatten(map(\(r) -> project(q, r, []), filtered))
  let distinct =
    if q.distinct then
      distinct_rows(projected, [])
    else
      projected
  let sorted =
    if length(plan.order) > 0 then
      sort_rows(distinct, plan.order)
    else
      distinct
  let skipped = drop(q.offset, sorted)
  let final =
    if q.limit >= 0 then
      take(q.limit, skipped)
    else
      skipped
  JObj([
      ("columns", JArr(map(\(s) -> JStr(snd(s)), q.select))),
      ("rows", JArr(map(JArr, final))),
    ])

fn demand(b : Bool, code : String) : Unit =
  if not(b) then
    reject(code)

fn reserved(s : String) : Bool =
  elem(
      to_upper(s),
      split(
          32,
          "SELECT DISTINCT AS FROM INNER JOIN LEFT OUTER ON WHERE GROUP BY HAVING ORDER ASC DESC NULLS FIRST LAST LIMIT OFFSET AND OR NOT IS NULL TRUE FALSE COALESCE COUNT SUM MIN MAX",
        ),
    )

type Table = Table {
  name: String,
  columns: List(Column),
  rows: List(List(Json))
}

fn validate_table(j : Json) : Table =
  fields(j, ["name", "columns", "rows"])
  let n = text(getfield(j, "name"))
  demand(name_ok(n), "INVALID_INPUT")
  let cs = map(validate_column, arr(getfield(j, "columns")))
  demand(length(cs) > 0, "INVALID_INPUT")
  demand(unique(map(\(c) -> c.name, cs)), "INVALID_INPUT")
  let rows = map(arr, arr(getfield(j, "rows")))
  for row in sof(rows) do
    demand(length(row) == length(cs), "INVALID_INPUT")
    for i in srange(0, length(cs)) do
      let v = at(row, i)
      demand(
          value_type(v) == at(cs, i).kind || is_null(v) && at(cs, i).nullable,
          "INVALID_INPUT",
        )
  Table { name = n, columns = cs, rows = rows }

fn validate_column(j : Json) : Column =
  fields(j, ["name", "type", "nullable"])
  let n = text(getfield(j, "name"))
  let t = text(getfield(j, "type"))
  demand(name_ok(n) && elem(t, ["int", "text", "bool"]), "INVALID_INPUT")
  let nullable =
    match getfield(j, "nullable") of
      JBool(b) => b
      _ =>
        reject("INVALID_INPUT")
        false
  Column {
    name = n,
    kind = t,
    qualifier = "",
    source = 0,
    index = 0,
    nullable = nullable
  }

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  let p = if op == "IS" then 4 else precedence(op)
  if p < minimum then
    left
  else
    demand(not(p == 4 && compared), "PARSE_ERROR")
    let ignored = pop()
    if op == "IS" then
      let negated = accept("NOT")
      expect("NULL")
      binary(node(if negated then "ISNOTNULL" else "ISNULL", [left]), minimum, true)
    else
      let right = expression(p + 1)
      binary(node(op, [left, right]), minimum, compared || p == 4)

fn coalesce_args(acc : List(Expr)) : List(Expr) =
  let e = expression(1)
  let next = append(acc, [e])
  if accept(",") then coalesce_args(next) else next

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Bool, Int)) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let nulls =
    if accept("NULLS") then
      if accept("FIRST") then 1 elif accept("LAST") then 2 else
        reject("PARSE_ERROR")
        0
    else
      0
  Cons((n, desc, nulls), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr),
  ls : List(Bool)
) : (List((String, String)), List(Expr), List(Bool)) =
  if elem(peek(), ["INNER", "JOIN", "LEFT"]) then
    let left = accept("LEFT")
    if left then let ignored = accept("OUTER") in () else let ignored = accept("INNER") in ()
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [left]))
  else
    (ss, js, ls)

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

fn work(request : Json) : Json =
  fields(request, ["protocol_version", "task", "input"])
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  let query_mode = has_field(input, "queries") && not(has_field(input, "commands"))
  let command_mode = has_field(input, "commands") && not(has_field(input, "queries"))
  demand(query_mode || command_mode, "INVALID_INPUT")
  fields(input, if query_mode then ["database", "queries"] else ["database", "commands"])
  let database = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, database)), "INVALID_INPUT")
  if command_mode then
    let commands = arr(getfield(input, "commands"))
    demand(length(commands) <= 2000, "INVALID_INPUT")
    run_commands(database, commands)
  else
    let queries = arr(getfield(input, "queries"))
    for q in sof(queries) do
      validate_query(q)
    let results = map(
        \(q) -> let plan = bind(parse_sql(text(getfield(q, "sql"))), database) in execute(if truth(getfield(q, "optimize")) then optimize(plan) else plan),
        queries,
      )
    JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(results))]))])

fn main() =
